#!/usr/bin/env python3
# faults-rows.py TREE [N]: the rows piece's faults (X's rows on the window: c_check_node_machine_rows.c, and the type
# column of c_check_node_census.c's sweep), one at a time: with no N, check every fault applies once and print how
# many; with N, apply fault N to its file in TREE in place and print its name.
import sys
ROWS = 'src/buster/compiler/c_check_node_machine_rows.c'
CENSUS = 'src/buster/compiler/c_check_node_census.c'
faults = []
def F(name, old, new, file=ROWS, nth=None):
    faults.append((name, file, old, new, nth))
# The reads.
LINED = "alive & (is_member | is_truth | (is_constant & ~discard & address_constant & has_object))"
F('reads-no-member', LINED, "alive & (is_truth | (is_constant & ~discard & address_constant & has_object))")
F('reads-no-truth', LINED, "alive & (is_member | (is_constant & ~discard & address_constant & has_object))")
F('reads-no-address', LINED, "alive & (is_member | is_truth)")
