F('reads-converts-no-target', CONVERTS, "_mm512_cmpneq_epi32_mask(targets, types)")
F('reads-converts-own-type', CONVERTS, "_mm512_test_epi32_mask(targets, targets)")
F('reads-converts-not-evaluated', "converts &= alive & value_context;", "converts &= value_context;")
F('reads-converts-any-context', "converts &= alive & value_context;", "converts &= alive;")
