F('reads-words-of-void-alone', "const uint64_t read_words = converts & ~voided;", "const uint64_t read_words = converts & voided;")
F('reads-word-class', "state->window_x_targets[x] = (uint8_t)word;", "state->window_x_targets[x] = (uint8_t)(word >> 8);")
F('reads-word-facts', "state->window_x_facts[x] = (uint8_t)(word >> 8);", "state->window_x_facts[x] = 0;")
F('reads-far-a-bit', "record->member_offset / 8 != 0 ?", "record->member_offset != 0 ?")
F('reads-far-inverted', "record->member_offset / 8 != 0 ?", "record->member_offset / 8 == 0 ?")
F('reads-local-unknown', "const bool local = known && machine->object_symbols[known ? object : 0] == 0;", "const bool local = machine->object_symbols[known ? object : 0] == 0;")
F('reads-local-inverted', "const bool local = known && machine->object_symbols[known ? object : 0] == 0;", "const bool local = known && machine->object_symbols[known ? object : 0] != 0;")
F('reads-offset-always', "(record->payload != 0 ? BUSTER_NODE_ROWS_BIT_OFFSET : 0u)", "(BUSTER_NODE_ROWS_BIT_OFFSET)")
F('reads-operand-second', "node_machine_class(machine, record->converted[0])", "node_machine_class(machine, record->converted[1])")
F('reads-list-quarter', "_mm512_set1_epi32((int32_t)(x + 16 * quarter))", "_mm512_set1_epi32((int32_t)(x + 16 * (quarter ^ 1)))")
# The shapes.
F('shapes-call-later', "_mm512_cmpge_epu8_mask(templates, _mm512_set1_epi8(NODE_MACHINE_TEMPLATE_BRANCH)) & ~is_call;", "_mm512_cmpge_epu8_mask(templates, _mm512_set1_epi8(NODE_MACHINE_TEMPLATE_BRANCH));")
F('shapes-later-from-an-update', "_mm512_cmpge_epu8_mask(templates, _mm512_set1_epi8(NODE_MACHINE_TEMPLATE_BRANCH)) & ~is_call;", "_mm512_cmpge_epu8_mask(templates, _mm512_set1_epi8(NODE_MACHINE_TEMPLATE_UPDATE));")
F('shapes-later-no-branches', "_mm512_cmpge_epu8_mask(templates, _mm512_set1_epi8(NODE_MACHINE_TEMPLATE_BRANCH)) & ~is_call;", "_mm512_cmpeq_epi8_mask(templates, _mm512_set1_epi8(NODE_MACHINE_TEMPLATE_UPDATE));")
