F('shapes-loads-in-an-address-context', "const __mmask64 loads = _mm512_testn_epi8_mask(contexts, _mm512_set1_epi8(BUSTER_CHECK_LOWER_TEMPLATE_ADDRESS)) &\n                                _mm512_testn_epi8_mask(facts, _mm512_set1_epi8(BUSTER_CHECK_LOWER_TYPE_ADDRESS));",
  "const __mmask64 loads = _mm512_testn_epi8_mask(facts, _mm512_set1_epi8(BUSTER_CHECK_LOWER_TYPE_ADDRESS));")
F('shapes-loads-an-address-type', "const __mmask64 loads = _mm512_testn_epi8_mask(contexts, _mm512_set1_epi8(BUSTER_CHECK_LOWER_TEMPLATE_ADDRESS)) &\n                                _mm512_testn_epi8_mask(facts, _mm512_set1_epi8(BUSTER_CHECK_LOWER_TYPE_ADDRESS));",
  "const __mmask64 loads = _mm512_testn_epi8_mask(contexts, _mm512_set1_epi8(BUSTER_CHECK_LOWER_TEMPLATE_ADDRESS));")
F('shapes-address-constant-kind', "const __mmask64 address_constant = _mm512_cmpeq_epi8_mask(constants, _mm512_set1_epi8(CHECK_CONSTANT_ADDRESS << 2));", "const __mmask64 address_constant = _mm512_cmpeq_epi8_mask(constants, _mm512_set1_epi8(CHECK_CONSTANT_FLOATING << 2));")
F('shapes-integer-constant-kind', "const __mmask64 integer_constant = _mm512_cmpeq_epi8_mask(constants, _mm512_set1_epi8(CHECK_CONSTANT_INTEGER << 2));", "const __mmask64 integer_constant = _mm512_cmpeq_epi8_mask(constants, _mm512_set1_epi8(CHECK_CONSTANT_FLOATING << 2));")
F('shapes-rvalue', "_mm512_set1_epi8(0x03)), _mm512_set1_epi8(CHECK_RVALUE));", "_mm512_set1_epi8(0x03)), _mm512_set1_epi8(CHECK_LVALUE));")
F('shapes-integer-short-of-u64', "const __mmask64 integer = _mm512_cmple_epu8_mask(from_i8, _mm512_set1_epi8(BUSTER_TYPED_CLASS_U64 - BUSTER_TYPED_CLASS_I8));", "const __mmask64 integer = _mm512_cmple_epu8_mask(from_i8, _mm512_set1_epi8(BUSTER_TYPED_CLASS_I64 - BUSTER_TYPED_CLASS_I8));")
F('shapes-below-u64-with-it', "const __mmask64 below_u64 = _mm512_cmple_epu8_mask(from_i8, _mm512_set1_epi8(BUSTER_TYPED_CLASS_I64 - BUSTER_TYPED_CLASS_I8));", "const __mmask64 below_u64 = _mm512_cmple_epu8_mask(from_i8, _mm512_set1_epi8(BUSTER_TYPED_CLASS_U64 - BUSTER_TYPED_CLASS_I8));")
F('shapes-narrow-short-of-short', "const __mmask64 narrow = _mm512_cmple_epu8_mask(from_i8, _mm512_set1_epi8(BUSTER_TYPED_CLASS_U16 - BUSTER_TYPED_CLASS_I8));", "const __mmask64 narrow = _mm512_cmple_epu8_mask(from_i8, _mm512_set1_epi8(BUSTER_TYPED_CLASS_U8 - BUSTER_TYPED_CLASS_I8));")
F('shapes-far-of-any', "const __mmask64 far = is_member & _mm512_test_epi8_mask(bits, _mm512_set1_epi8(BUSTER_NODE_ROWS_BIT_FAR));", "const __mmask64 far = _mm512_test_epi8_mask(bits, _mm512_set1_epi8(BUSTER_NODE_ROWS_BIT_FAR));")
F('shapes-local-without-object', "const __mmask64 local = has_object & _mm512_test_epi8_mask(bits, _mm512_set1_epi8(BUSTER_NODE_ROWS_BIT_LOCAL));", "const __mmask64 local = _mm512_test_epi8_mask(bits, _mm512_set1_epi8(BUSTER_NODE_ROWS_BIT_LOCAL));")
F('shapes-offset-without-object', "const __mmask64 offset = has_object & _mm512_test_epi8_mask(bits, _mm512_set1_epi8(BUSTER_NODE_ROWS_BIT_OFFSET)) &", "const __mmask64 offset = _mm512_test_epi8_mask(bits, _mm512_set1_epi8(BUSTER_NODE_ROWS_BIT_OFFSET)) &")
