F('shapes-sum-loads', "pointer = _mm512_mask_mov_epi8(pointer, loads & _mm512_cmpeq_epi8_mask(codes, _mm512_set1_epi8(CHECK_OP_SUBSCRIPT)),", "pointer = _mm512_mask_mov_epi8(pointer, loads & _mm512_cmpneq_epi8_mask(codes, _mm512_set1_epi8(CHECK_OP_SUBTRACT)),")
